def error(obj, level, message):
    if settings.error_action == 'exit':
        print('{} {}: {}'.format(obj.__name__, level, message))
        if settings.fatal_traceback:
            traceback.print_exc()
        sys.exit(1)
    else:
        if level.lower() == 'warn':
            print('{} {}: {}'.format(obj.__name__, level, message))
        elif level.lower() == 'fatal':
            print('{} {}: {}'.format(obj.__name__, level, message))
            if settings.fatal_traceback:
