        else:
            templates_vars[var_name] = var
    @processor(Action.NoOp)
    async def no_op(params: models.IsNone):
        pass
    if debug:
        for action in Action:
            if action not in processors:
                raise ExecutionError(f"{action.value} does not have a processor.")
    async def process_action(action, value):
        self.last_action = action
        if debug and action not in ALLOWED_DEBUG_ACTIONS:
            return
        params = model_validator(action, value)
        try:
            processor_func = processors[action]
        except KeyError:
            raise ExecutionError(f"Unhandled action '{action.value}'.")
        await processor_func(params)
    last_cond_action_result = None
    for entry in self.actions:
        for enum, value in entry.items():
            enum = self._get_actions_enum(enum)
            if isinstance(enum, Action):
                try:
                    await process_action(enum, value)
                except StopExecution:
                    return bool(last_expel_action)
            elif isinstance(enum, Condition):
                _eval = await self._evaluate_conditions([{enum.value: value}],
                                                        cog=cog, user=user, message=message,
                                                        guild=guild, templates_vars=templates_vars,
                                                        debug=debug)
                last_cond_action_result = _eval[0]
            elif isinstance(enum, ConditionBlock):
                _eval = await self._evaluate_conditions_block(block=[{enum.value: value}],
                                                              cog=cog, user=user, message=message,
                                                              guild=guild, templates_vars=templates_vars,
                                                              debug=debug)
                last_cond_action_result = bool(_eval)
            elif isinstance(enum, ConditionalActionBlock):
                is_true = enum == ConditionalActionBlock.IfTrue and last_cond_action_result is True
                is_false = enum == ConditionalActionBlock.IfFalse and last_cond_action_result is False
                if is_true or is_false:
                    for raw_action in value:
                        for action, subvalue in raw_action.items():
                            action = self._get_actions_enum(action)
                            try:
                                await process_action(action, subvalue)
                            except StopExecution:
                                return bool(last_expel_action)
    return bool(last_expel_action)

class TrailingSlashHandler(web.RequestHandler):
    def get(self):
        uri = self.request.path.rstrip("/")
        if uri:
            self.redirect('?'.join((uri, self.request.query)))
    post = put = get
    def get(self):
        html = self.render_template("main.html")
        self.write(html)

class TrailingSlashHandler(web.RequestHandler):
    def get(self):
        path, *rest = self.request.uri.partition("?")
        path = "/" + path.strip("/")
        new_uri = "".join([path, *rest])
        self.redirect(new_uri)
    post = put = get
    def get(self):
        html = self.render_template("main.html")
        self.write(html)

class LLMMathChain(Chain):
    output_key: str = "answer"
    def output_keys(self) -> List[str]:
        """Expect output key.
        :meta private:
        """
        return [self.output_key]
    def _process_llm_result(self, t: str) -> Dict[str, str]:
        python_executor = PythonREPL()
        self.callback_manager.on_text(t, color="green", verbose=self.verbose)
        t = t.strip()
        if t.startswith("```python"):
            code = t[9:-4]
            output = python_executor.run(code)
            self.callback_manager.on_text("\nAnswer: ", verbose=self.verbose)
            self.callback_manager.on_text(output, color="yellow", verbose=self.verbose)
            answer = "Answer: " + output
        elif t.startswith("Answer:"):
            answer = t
        elif "Answer:" in t:
            answer = "Answer: " + t.split("Answer:")[-1]
        else:
            raise ValueError(f"unknown format from LLM: {t}")
        return {self.output_key: answer}
    async def _aprocess_llm_result(self, t: str) -> Dict[str, str]:
        python_executor = PythonREPL()
        if self.callback_manager.is_async:
            await self.callback_manager.on_text(t, color="green", verbose=self.verbose)
        else:
            self.callback_manager.on_text(t, color="green", verbose=self.verbose)
        t = t.strip()
        if t.startswith("```python"):
            code = t[9:-4]
            output = python_executor.run(code)
            if self.callback_manager.is_async:
                await self.callback_manager.on_text("\nAnswer: ", verbose=self.verbose)
                await self.callback_manager.on_text(
                    output, color="yellow", verbose=self.verbose
                )
            else:
                await self.callback_manager.on_text("\nAnswer: ", verbose=self.verbose)
                await self.callback_manager.on_text(
                    output, color="yellow", verbose=self.verbose
                )
            answer = "Answer: " + output
        elif t.startswith("Answer:"):
            answer = t
        elif "Answer:" in t:
            answer = "Answer: " + t.split("Answer:")[-1]
        else:
            raise ValueError(f"unknown format from LLM: {t}")
        return {self.output_key: answer}
        return self._process_llm_result(t)
        return await self._aprocess_llm_result(t)

class LLMMathChain(Chain):
    output_key: str = "answer"
    def output_keys(self) -> List[str]:
        """Expect output key.
        :meta private:
        """
        return [self.output_key]
    def _evaluate_expression(self, expression: str) -> str:
        try:
            local_dict = {"pi": math.pi, "e": math.e}
            output = str(
                numexpr.evaluate(
                    expression.strip(),
                    global_dict={},
                    local_dict=local_dict,
                )
            )
        except Exception as e:
            raise ValueError(f"{e}. Please try again with a valid numerical expression")
        return re.sub(r"^\[|\]$", "", output)
    def _process_llm_result(self, llm_output: str) -> Dict[str, str]:
        self.callback_manager.on_text(llm_output, color="green", verbose=self.verbose)
        llm_output = llm_output.strip()
        text_match = re.search(r"^```text(.*?)```", llm_output, re.DOTALL)
        if text_match:
            expression = text_match.group(1)
            output = self._evaluate_expression(expression)
            self.callback_manager.on_text("\nAnswer: ", verbose=self.verbose)
            self.callback_manager.on_text(output, color="yellow", verbose=self.verbose)
            answer = "Answer: " + output
        elif llm_output.startswith("Answer:"):
            answer = llm_output
        elif "Answer:" in llm_output:
            answer = "Answer: " + llm_output.split("Answer:")[-1]
        else:
            raise ValueError(f"unknown format from LLM: {llm_output}")
        return {self.output_key: answer}
    async def _aprocess_llm_result(self, llm_output: str) -> Dict[str, str]:
        if self.callback_manager.is_async:
            await self.callback_manager.on_text(
                llm_output, color="green", verbose=self.verbose
            )
        else:
            self.callback_manager.on_text(
                llm_output, color="green", verbose=self.verbose
            )
        llm_output = llm_output.strip()
        text_match = re.search(r"^```text(.*?)```", llm_output, re.DOTALL)
        if text_match:
            expression = text_match.group(1)
            output = self._evaluate_expression(expression)
            if self.callback_manager.is_async:
                await self.callback_manager.on_text("\nAnswer: ", verbose=self.verbose)
                await self.callback_manager.on_text(
                    output, color="yellow", verbose=self.verbose
                )
            else:
                await self.callback_manager.on_text("\nAnswer: ", verbose=self.verbose)
                await self.callback_manager.on_text(
                    output, color="yellow", verbose=self.verbose
                )
            answer = "Answer: " + output
        elif llm_output.startswith("Answer:"):
            answer = llm_output
        elif "Answer:" in llm_output:
            answer = "Answer: " + llm_output.split("Answer:")[-1]
        else:
            raise ValueError(f"unknown format from LLM: {llm_output}")
        return {self.output_key: answer}
        return self._process_llm_result(llm_output)
        return await self._aprocess_llm_result(llm_output)

